import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be shown in full in diagnostic output.
SECRET_KEYS = frozenset({"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"})


def _unquote(value):
    """Strip one pair of matching surrounding quotes, if present."""
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value


def parse_dotenv_line(line):
    """Return (key, value) for a dotenv line, or None for blank/comment/malformed lines.

    Supports ``KEY=value``, an optional leading ``export``, single or double
    quotes around the value, and ``=`` characters inside the value.
    """
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export ") or line.startswith("export\t"):
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    if not key:
        return None
    return key, _unquote(value.strip())


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = parse_dotenv_line(line)
            if parsed is not None:
                values[parsed[0]] = parsed[1]
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def mask_secret(value):
    """Mask a secret for display, keeping only a short prefix and the length."""
    if value is None:
        return None
    if len(value) <= 8:
        return "****"
    return "%s****(%d chars)" % (value[:4], len(value))


def describe_config(config):
    """Return (key, display_value, source) rows with secrets masked."""
    rows = []
    for key, (value, source) in config.items():
        if key in SECRET_KEYS:
            value = mask_secret(value)
        rows.append((key, "<unset>" if value is None else value, source))
    return rows

